out={}
for vid,s in src.items():
    P,N,Q,A,X=D[vid]
    assert len(P)==3 and len(N)==len(s['nouns']), vid
    assert [p['text'] for p in s['phrases']]==s['recall'][:3], vid
    R=P+X; assert len(R)==len(s['recall']), (vid,len(R),len(s['recall']))
    out[vid]={"phrases":P,"nouns":N,"question":Q,"answer":A,"captions":{},"recall":R}
assert set(D)==set(src)
json.dump(out,open(f'{H}/tr/b001/fr/tr.json','w'),ensure_ascii=False,indent=1)
